
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"MermaidsGoldAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		    var tmpMess=k.data.split("#");
		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.ppx.dkd!=undefined){
			
			if(gameController.hyl!=parseInt(tmpMess[1])){
				
			gameController.hyl=parseInt(tmpMess[1]);	
			gameController.ppx.dkd.zxt("creditd", "#mmm", [gameController.irs(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
